import { readFileSync } from "node:fs";
import { join } from "node:path";
import { pageSeo } from "./seo";
import { stones } from "./stoneData";
import { services } from "./serviceData";
import { equipmentCategories } from "./machineData";
import { membershipPlans } from "./membershipPlans";
import { legalVersion } from "./legalDocuments";
import { safeJsonLd } from "./seo";

const body = readFileSync(join(process.cwd(), "lib/marketBody.html"), "utf8");
const panelTitle = {
  "dogal-tas": "Doğal taş koleksiyonu",
  firmalar: "Firma rehberi",
  "alim-talepleri": "Alım Talepleri",
  "makine-sarf": "Makine ve sarf pazarı",
  hizmetler: "Sektörel hizmetler",
} as const;
const panelSubtitle = {
  "dogal-tas": "Türe ve formata göre doğal taşlar",
  firmalar: "Onaylı üretici ve tedarikçiler",
  "alim-talepleri": "Tedarikçi hesabına özel talepler",
  "makine-sarf": "Ekipman ve sarf ürünleri",
  hizmetler: "Taş ticaretini destekleyen hizmetler",
} as const;

const navigation = [
  { tab: "stones", slug: "dogal-tas", title: "Doğal Taş" },
  { tab: "companies", slug: "firmalar", title: "Firmalar" },
  { tab: "machines", slug: "makine-sarf", title: "Makine &amp; Sarf" },
  { tab: "services", slug: "hizmetler", title: "Hizmetler" },
  { tab: "requests", slug: "alim-talepleri", title: "Alım Talepleri" },
] as const;

function stoneCards(): string {
  return stones.map((stone, index) => `<article class="card card-guide"><div class="card-media has-illustration stone-visual"><img src="/market/images/marble/${stone.image}" alt="${stone.name} mermer koleksiyonu" loading="lazy" decoding="async" width="1000" height="730"><span class="card-index">${String(index + 1).padStart(2, "0")}</span></div><div class="card-body"><span class="card-origin">TÜR REHBERİ</span><span class="card-kicker">${stone.forms.join(" · ")}</span><h4><a href="/tr/dogal-tas/${stone.slug}">${stone.name}</a></h4><p>${stone.type} · ${stone.city}</p><div class="card-footer"><span>${stone.color}</span><button type="button" data-card="${index}">Detayları gör →</button></div></div></article>`).join("");
}

function serviceCards(): string {
  return services.map((service, index) => `<article class="card card-guide"><div class="card-media has-illustration"><img src="/market/images/services/${service.image}.webp" alt="${service.title} hizmet kategorisi" loading="lazy" decoding="async" width="1000" height="730"><span class="card-index">${String(index + 1).padStart(2, "0")}</span></div><div class="card-body"><span class="card-origin">TÜR REHBERİ</span><span class="card-kicker">${service.subtitle}</span><h4>${service.title}</h4><p>${service.subtitle}</p><div class="card-footer"><span>Hizmet türü</span><button type="button" data-card="${index}">Detayları gör →</button></div></div></article>`).join("");
}

function machineCards(): string {
  return equipmentCategories.map((item, index) => `<article class="card card-guide"><div class="card-media has-illustration"><img src="/market/images/machines/${item.image}.webp" alt="${item.title} makine ve sarf kategorisi" loading="lazy" decoding="async" width="1000" height="730"><span class="card-index">${String(index + 1).padStart(2, "0")}</span></div><div class="card-body"><span class="card-origin">TÜR REHBERİ</span><span class="card-kicker">${item.subtitle}</span><h4>${item.title}</h4><p>${item.detail}</p><div class="card-footer"><span>Kategori bilgisi</span><button type="button" data-card="${index}">Detayları gör →</button></div></div></article>`).join("");
}

// The front page offers navigation into all four marketplaces, rather than
// presenting the natural stone catalogue as if it were the entire website.
type DirectorySeed = {status: string; companies: {id: string; name: string; city: string; activity_type: string; section: string; logo_url: string}[]; catalogStatus: string; items: {id: string; company_id: string; title: string; category: string; description: string; image_urls: string[]}[]};
const escape = (value: unknown) => String(value ?? "").replace(/[&<>"']/g, character => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[character]!));
function logo(company: DirectorySeed["companies"][number]) {
  return company.logo_url ? `<img class="company-logo" src="${escape(company.logo_url)}" alt="${escape(company.name)} logo" width="64" height="64" loading="lazy" />` : `<span class="company-logo-fallback">${escape(company.name.slice(0,2).toUpperCase())}</span>`;
}
function firmPreview(directory?: DirectorySeed) {
  const count=directory?.companies.length||0;
  return `<span class="discovery-media discovery-company-cover"><img src="/market/images/marble/beige.webp" width="560" height="360" alt="Doğal taş firma rehberi" loading="lazy"/><span class="company-cover-caption"><small>FİRMA REHBERİ</small><strong>Üreticiler ve tedarikçiler</strong><span>${count ? `${count} yayınlanmış firma` : "Firmaları keşfedin"}</span></span></span>`;
}
function directoryRows(directory: DirectorySeed) {
  return directory.companies.map((company, index) => `<a class="company-row" href="/tr/firmalar/${escape(company.id)}"><span class="company-number">${String(index+1).padStart(2,"0")}</span><span class="company-thumb has-logo">${logo(company)}</span><span class="company-name"><strong>${escape(company.name)}</strong><small>${escape(company.city)}</small></span><span class="company-field">${escape(company.activity_type)}</span><span class="company-action">Firma profili →</span></a>`).join("");
}
function catalogCards(directory: DirectorySeed, category: string) {
  const kinds = category === "dogal-tas" ? ["stone"] : category === "hizmetler" ? ["service"] : ["machine","supplies"];
  const items = directory.items.filter(item => kinds.includes(item.category));
  return `<div class="listing-heading"><span>Firma katalogları</span><small>${items.length}</small></div>${items.length ? items.map(item => { const company = directory.companies.find(row => row.id === item.company_id); return `<article class="card card-real"><div class="card-media has-illustration"><img src="${escape(item.image_urls[0])}" alt="${escape(item.title)}" width="1000" height="730" loading="lazy" /></div><div class="card-body"><span class="card-origin">FİRMA KATALOĞU</span><h4><button type="button" data-card="catalog-${escape(item.id)}">${escape(item.title)}</button></h4><p>${escape(item.description)}</p>${company ? `<a href="/tr/firmalar/${escape(company.id)}">${escape(company.name)} →</a>` : ""}<div class="card-footer"><button type="button" data-card="catalog-${escape(item.id)}">Kataloğu incele →</button></div></div></article>`; }).join("") : `<p class="listing-empty">${directory.catalogStatus === "error" ? "Katalog bilgisi alınamadı. Sayfayı yeniden deneyin." : "Bu kategoride henüz yayınlanmış firma kataloğu bulunmuyor."}</p>`}<div class="listing-heading listing-guide-heading"><span>Tür rehberi</span><small>Taş, makine ve hizmet türlerini inceleyin.</small></div>`;
}
function homeCategoryCards(directory?: DirectorySeed): string {
  const categories = [
    { slug: "dogal-tas", title: "Doğal Taş", subtitle: "Mermer ve traverten çeşitlerini keşfedin", image: "/market/images/marble/white.webp", alt: "Doğal taş kategorisi · mermer plakalar" },
    { slug: "firmalar", title: "Firmalar", subtitle: "Üretici ve tedarikçi rehberini inceleyin", image: "", alt: "" },
    { slug: "makine-sarf", title: "Makine ve Sarf", subtitle: "Kesim ekipmanları ve sarf kategorileri", image: "/market/images/machines/elmas-tel.webp", alt: "Makine ve sarf kategorisi · mermer kesimi" },
    { slug: "hizmetler", title: "Sektörel Hizmetler", subtitle: "Nakliye, gümrük ve sektör hizmetleri", image: "/market/images/services/lojistik.webp", alt: "Sektörel hizmetler · doğal taş lojistiği" },
  ];
  return categories.map((item,index) => `<article class="discovery-card"><a href="/tr/${item.slug}" data-tab="${item.slug === 'dogal-tas' ? 'stones' : item.slug === 'firmalar' ? 'companies' : item.slug === 'makine-sarf' ? 'machines' : 'services'}" class="discovery-link">${item.image ? `<span class="discovery-media"><img src="${item.image}" alt="${item.alt}" loading="lazy" decoding="async" width="560" height="360" /></span>` : firmPreview(directory)}<span class="discovery-copy"><small>0${index+1} / MARBLE BORSA</small><strong>${item.title}</strong><span>${item.subtitle}</span><b>Keşfet <span aria-hidden="true">↗</span></b></span></a></article>`).join("");
}

const editorialContent = {
  title: "Mermer satın alma süreci doğru bilgi ve doğrudan temasla başlar",
  description: "Mermer blok, plaka, ebatlı ürün, makine, sarf ve sektör hizmetleri arayan işletmeler için ihtiyaç belirleme, teklif toplama ve firmalarla doğrudan iletişim adımlarını açıklıyoruz. Marble Borsa kendi adına mermer satmaz; alıcılarla üretici, tedarikçi ve hizmet sağlayıcıları buluşturan B2B keşif ve teklif platformudur.",
};

export type MarketplaceCategory = keyof typeof pageSeo | "alim-talepleri";

export function marketMarkup(category?: MarketplaceCategory, profile = false, directory?: DirectorySeed): string {
  const heading = category === "firmalar" ? "Firma rehberi" : category === "makine-sarf" ? "Makine ve sarf malzemeleri" : category === "hizmetler" ? "Doğal taş sektörü hizmetleri" : category === "dogal-tas" ? "Mermer ve doğal taş çeşitleri" : category === "alim-talepleri" ? "Alım Talepleri" : category && category in pageSeo
    ? pageSeo[category as keyof typeof pageSeo].title
    : "Mermer ve doğal taş için doğrudan teklif alın.";
  const categoryIntro = {"dogal-tas":"Mermer ve traverten türlerini karşılaştırın; yayınlanmış firma kataloglarını ve doğal taş üreticilerini inceleyin.","firmalar":"Doğal taş üreticilerini, makine ve sarf tedarikçilerini, lojistik ve sektör hizmeti sağlayıcılarını tek rehberde bulun.","makine-sarf":"Kesim makineleri, elmas takımlar ve sarf malzemeleri için katalogları inceleyin; ekipman ihtiyacınızı belirtin.","hizmetler":"Lojistik, gümrükleme, kalite kontrol ve taş ticaretini destekleyen hizmet firmalarını bulun."};
  const intro = category && category in categoryIntro ? categoryIntro[category as keyof typeof categoryIntro] : "Mermer, traverten, makine ve doğal taş sektörü hizmetlerini inceleyin. Üretici ve tedarikçilerden doğrudan teklif isteyin; yanıtları Profil sayfanızda değerlendirin.";
  const active = category || "home";
  const initialCards = !category ? homeCategoryCards(directory) : category === "dogal-tas" ? stoneCards() : category === "hizmetler" ? serviceCards() : category === "makine-sarf" ? machineCards() : category === "firmalar" && directory ? directoryRows(directory) : category === "alim-talepleri" ? `<div class="access-card"><h4>Alım taleplerini görüntülemek için firma hesabınızla giriş yapın.</h4><p>Onaylı ve üyeliği aktif firmalar kendilerine uygun talepleri inceleyebilir.</p><div class="access-actions"><button type="button" class="button dark" data-profile-login>Giriş Yap</button><button type="button" class="button outline" data-signup-open>Firma Hesabı Oluştur</button></div></div>` : "";
  const topNav = navigation.map(({ tab, slug, title }) =>
    `<a href="/tr/${slug}" data-tab="${tab}" class="${slug === active ? "active" : ""}">${title}</a>`
  ).join("");
  const guideNav = '<a class="guide-nav-link" href="/tr/rehber">Mermer Rehberi</a>';
  const sideNav = navigation.map(({ tab, slug, title }) =>
    `<a href="/tr/${slug}" data-tab="${tab}" class="${slug === active ? "active" : ""}">${title}<b>›</b></a>`
  ).join("");
  const markup = body
    .replace('<button class="text-button" id="panelAction"></button>', '<button class="text-button" id="panelAction" hidden></button>')
    .replace('<button class="button filter-button" id="resetSearch"></button>', '<button class="button filter-button" id="resetSearch">Temizle</button>')
    .replace('<strong id="asideTitle"></strong>', '<strong id="asideTitle">Teklif süreci</strong>')
    .replace('<p id="asideBody"></p>', '<p id="asideBody">İhtiyacınızı, miktarı ve teslim yerini belirtin. Gelen teklifleri Profil sayfanızda inceleyin.</p>')
    .replace('<div class="panel-label" id="categoriesLabel"></div>', '<div class="panel-label" id="categoriesLabel">KATEGORİLER</div>')
    .replace('<span id="flowLabel"></span>', '<span id="flowLabel">NASIL ÇALIŞIR?</span>')
    .replace('<span id="flow1"></span>', '<span id="flow1">Ürün veya hizmet bulun</span>')
    .replace('<span id="flow2"></span>', '<span id="flow2">Talebinizi yazın</span>')
    .replace('<span id="flow3"></span>', '<span id="flow3">Doğrudan teklif alın</span>')
    .replace('<div id="toast" role="status" aria-live="polite"></div>', `<script type="application/json" id="mb-public-directory">${safeJsonLd(directory || null)}</script><script type="application/json" id="mb-company-data">[]</script><script type="application/json" id="mb-membership-plans">${safeJsonLd({ plans: Object.fromEntries(Object.entries(membershipPlans).map(([role, plan]) => [role, { durationMonths: plan.durationMonths }])), legalVersion })}</script><div id="toast" role="status" aria-live="polite"></div>`)
    .replace('<span id="stripText"></span>', '<span id="stripText">Doğal taş tedarik platformu</span>')
    .replace('href="./" aria-label="Marble Borsa ana sayfa"', 'href="/" aria-label="Marble Borsa ana sayfa"')
    .replace('<nav id="topNav" aria-label="Ana gezinme"></nav>', `<nav id="topNav" aria-label="Ana gezinme"><a href="/" data-tab="home" class="${active === "home" ? "active" : ""}">Ana Sayfa</a>${topNav}${guideNav}</nav>`)
    .replace('<div id="sideNav"></div>', `<div id="sideNav"><a href="/" data-tab="home" class="${active === "home" ? "active" : ""}">Genel Bakış<b>›</b></a>${sideNav}</div>`)
    .replace('<button class="button bright" id="browseButton"></button>', '<button class="button bright" id="browseButton">Taşları keşfet</button>')
    .replace('<button class="button ghost" id="newRequestButton"></button>', '<button class="button ghost" id="newRequestButton" hidden>Teklif talebi oluştur</button>')
    .replace('<h1 id="heroTitle"></h1>', `<h1 id="heroTitle">${heading}</h1>`)
    .replace('<p id="heroLead"></p>', `<p id="heroLead">${intro}</p>`)
    .replace('<h2 id="marketHeading"></h2>', '<h2 id="marketHeading">Doğal taş ticaretinin buluşma noktası</h2>')
    .replace('<p id="marketIntro"></p>', '<p id="marketIntro">Taşları, firmaları, makine ve hizmetleri keşfedin. İşletmelerle doğrudan iletişime geçin.</p>')
    .replace('<small id="stoneNote"></small>', '<small id="stoneNote">DOĞAL TAŞ KOLEKSİYONU</small>')
    .replace('<strong id="stoneName"></strong>', '<strong id="stoneName">Afyon White</strong>')
    .replace('<span id="stoneCount"></span>', '<span id="stoneCount">01 / 04</span>')
    .replace('<h3 id="panelTitle"></h3>', `<h3 id="panelTitle">${category && category in panelTitle ? panelTitle[category as keyof typeof panelTitle] : "Platformu keşfedin"}</h3>`)
    .replace('<p id="panelSubtitle"></p>', `<p id="panelSubtitle">${category && category in panelSubtitle ? panelSubtitle[category as keyof typeof panelSubtitle] : "İhtiyacınıza uygun bir kategori seçin"}</p>`)
    .replace('<span id="resultCount" aria-live="polite"></span>', `<span id="resultCount" aria-live="polite">${category === "firmalar" ? `${directory?.companies.length || 0} firma` : category === "alim-talepleri" ? "" : category && initialCards ? `${category === "hizmetler" ? services.length : category === "makine-sarf" ? equipmentCategories.length : stones.length} sonuç` : ""}</span>`)
    .replace('<div id="cards" class="cards"></div>', `<div id="cards" class="cards${!category ? " discovery-grid" : category === "firmalar" ? " company-list" : ""}">${category && initialCards && ["dogal-tas","makine-sarf","hizmetler"].includes(category) && directory ? catalogCards(directory, category) : ""}${initialCards}</div>`)
    .replace('<div id="emptyState" class="empty-state" hidden></div>', `<div id="emptyState" class="empty-state"${category === "firmalar" && !directory?.companies.length ? "" : " hidden"}>${category === "firmalar" ? directory?.status === "error" ? "Firma bilgisi alınamadı. Lütfen sayfayı tekrar deneyin." : "Henüz yayınlanmış firma bulunmuyor." : ""}</div>`)
    .replace('    <!-- mb-content-insertion -->', (!profile && (!category || category === "dogal-tas") ? `<section class="market-guide-preview" aria-labelledby="guide-preview-heading">
      <div><span class="guide-kicker" id="guide-preview-kicker">MERMER REHBERİ</span><h2 id="guide-preview-heading">Mermer almadan önce bilmeniz gerekenler</h2><p id="guide-preview-desc">Mermer nasıl alınır, fiyatlar nasıl karşılaştırılır, blok ve plaka seçiminde nelere dikkat edilir? Bağımsız satın alma rehberlerimizde öğrenin.</p></div>
      <a id="guide-preview-link" href="/tr/rehber">Rehberleri keşfet →</a></section>
      <section class="market-sourcing-preview" aria-label="Mermer teklifi ve B2B tedarik">
        <a class="market-sourcing-card" id="sourcing-quote-link" href="/tr/mermer-teklifi-al">
          <small id="sourcing-quote-kicker">ALICILAR İÇİN</small><strong id="sourcing-quote-title">Mermer teklifi nasıl alınır?</strong>
          <span id="sourcing-quote-desc">Blok ve plaka ihtiyacınız için üretici ve tedarikçilerden doğrudan teklif isteyin.</span>
          <b id="sourcing-quote-action">Teklif sürecini incele →</b>
        </a>
        <a class="market-sourcing-card" id="sourcing-b2b-link" href="/tr/b2b-mermer">
          <small id="sourcing-b2b-kicker">İŞLETMELER İÇİN</small><strong id="sourcing-b2b-title">B2B mermer ve doğal taş tedariki</strong>
          <span id="sourcing-b2b-desc">Alıcılarla üretici firmaları buluşturan doğrudan ticaret modelini keşfedin.</span>
          <b id="sourcing-b2b-action">B2B platformunu keşfet →</b>
        </a>
      </section>` : "") + '    <!-- mb-content-insertion -->');
  const withBreadcrumb = !profile
    ? markup.replace('<main>', `<main><nav class="seo-breadcrumb" aria-label="Sayfa yolu"${!category ? " hidden" : ""}><a href="/">Ana Sayfa</a><span aria-hidden="true">›</span><span aria-current="page">${category && category in panelTitle ? panelTitle[category as keyof typeof panelTitle] : "Ana Sayfa"}</span></nav>`)
    : markup;
  const withEditorial = withBreadcrumb.replace('    <!-- mb-content-insertion -->', `
      <section class="market-editorial" id="marketEditorial" aria-labelledby="marketEditorialTitle">
        <div class="market-editorial-copy">
          <span class="market-editorial-eyebrow" id="marketEditorialEyebrow">B2B DOĞAL TAŞ BİLGİ MERKEZİ</span>
          <h2 id="marketEditorialTitle">${editorialContent.title}</h2>
          <p id="marketEditorialDescription">${editorialContent.description}</p>
        </div>
        <nav class="market-editorial-links" aria-label="Mermer tedarik rehberleri">
          <a id="marketEditorialQuote" href="/tr/mermer-teklifi-al">Mermer teklifi alma süreci <span aria-hidden="true">↗</span></a>
          <a id="marketEditorialB2b" href="/tr/b2b-mermer">B2B mermer ve doğal taş <span aria-hidden="true">↗</span></a>
          <a id="marketEditorialGuide" href="/tr/rehber">Alım ve taş seçimi rehberi <span aria-hidden="true">↗</span></a>
        </nav>
      </section>
      <!-- mb-content-insertion -->`);
  const enhanced = !profile && !category ? withEditorial.replace('      <!-- mb-content-insertion -->', `
    <section class="seo-help mb-process" aria-labelledby="purchase-scenarios"><div class="sourcing-heading"><span class="guide-kicker">NASIL ÇALIŞIR?</span><h2 id="purchase-scenarios">İhtiyaçtan teklife, üç adımda</h2><p>Doğal taş, makine ve sektör hizmetleri için doğru firmaya ulaşın.</p></div><ol class="sourcing-step-list"><li><span class="sourcing-number" aria-hidden="true">01</span><h3>İhtiyacınızı belirtin</h3><p>Ürün veya hizmeti seçin; miktarı, teknik özellikleri ve teslim yerini talebinize ekleyin.</p><a href="/tr/mermer-teklifi-al">Talep hazırlama rehberi <span aria-hidden="true">↗</span></a></li><li><span class="sourcing-number" aria-hidden="true">02</span><h3>Teklifleri karşılaştırın</h3><p>Gelen teklifleri Profil sayfanızdan inceleyin. Fiyatı, ürün özelliklerini ve teslim koşullarını birlikte değerlendirin.</p><a href="/tr/profil">Profilinize gidin <span aria-hidden="true">↗</span></a></li><li><span class="sourcing-number" aria-hidden="true">03</span><h3>Firmayla doğrudan görüşün</h3><p>Numune, ödeme ve teslim ayrıntılarını seçtiğiniz firmayla netleştirin. Ticaret doğrudan sizinle firma arasında gerçekleşir.</p><a href="/tr/firmalar">Firmaları inceleyin <span aria-hidden="true">↗</span></a></li></ol></section>
    <section class="seo-help" aria-labelledby="market-faq"><span class="guide-kicker">SIK SORULAN SORULAR</span><h2 id="market-faq">Aklınızdaki sorular</h2><p class="faq-intro">Üyelikten ilk teklifinize kadar merak ettiğiniz ayrıntılar.</p>
    <details><summary>Marble Borsa doğrudan mermer satıyor mu?</summary><p>Marble Borsa alıcıları bağımsız üretici, tedarikçi ve hizmet sağlayıcılarla buluşturur. Teklif, ödeme ve teslim koşulları taraflar arasında belirlenir.</p></details>
    <details><summary>Mermer fiyatları neden sabit gösterilmiyor?</summary><p>Fiyat taşın türüne, partiye, ölçüye, yüzey işlemine, miktara ve teslim koşullarına göre değişir. İhtiyacınızı açıklayarak firmalardan teklif alabilirsiniz.</p></details>
    <details><summary>Teklif talebinde hangi bilgileri yazmalıyım?</summary><p>Ürün veya hizmet, ölçü ve format, miktar ve birim, teslim yeri ve beklenen teslim tarihini belirtin. <a href="/tr/mermer-teklifi-al">Teklif rehberinde</a> ayrıntılı hazırlık adımlarını inceleyebilirsiniz.</p></details>
    <details><summary>Firmamı nasıl yayınlayabilirim?</summary><p>Uygun firma hesap türüyle kaydolun ve e-posta adresinizi doğrulayın. Profilinizde firma bilgileri, belgeler ve logo alanlarını tamamlayın. Yönetici onayı, aktif üyelik ve rehber görünürlüğü izni sonrasında firma rehberinde yer alabilirsiniz.</p></details>
    <details><summary>Makine, sarf ve sektör hizmetleri de bulunuyor mu?</summary><p>Evet. <a href="/tr/makine-sarf">Makine ve sarf</a> ile <a href="/tr/hizmetler">hizmetler</a> bölümlerinden ilgili kategorileri ve yayınlanan firma kataloglarını inceleyebilirsiniz.</p></details>
    <details><summary>Hangi hesap türünü seçmeliyim?</summary><p>Taş almak için Alıcı; taş, makine veya sarf ürünü satmak için Üretici / Tedarikçi; lojistik, gümrük ve benzeri sektör hizmetleri sunmak için Hizmet Sağlayıcı hesabını seçin.</p></details>
    <details><summary>E-posta onayından sonra firma hesabım hemen açılır mı?</summary><p>E-posta doğrulaması hesap erişimi için gereklidir. Firma yetkileri ayrıca belgelerin incelenmesi, yönetici onayı ve üyeliğin etkinleştirilmesinden sonra açılır. Başvurunuzun durumunu <a href="/tr/profil">Profil</a> sayfasında takip edebilirsiniz.</p></details>
    <details><summary>Tedarikçi hesabıyla alım talebi açabilir miyim?</summary><p>Taş alım taleplerini yalnızca alıcı hesapları açabilir. Aktif tedarikçiler makine ve sarf ürünü ile sektör hizmetleri için talep oluşturabilir. Aktif hizmet sağlayıcılar makine ve sarf ürünü talebi açabilir.</p></details>
    <details><summary>Gelen teklifleri nereden görebilirim?</summary><p>Giriş yaptıktan sonra Profil sayfanızda ilgili talebi açarak gelen teklifleri inceleyebilirsiniz. Fiyat, birim, teslim koşulları ve ürün özelliklerini karşılaştırın; sipariş ayrıntılarını teklif veren firmayla netleştirin.</p></details>
    <details><summary>Onaylanan firmam neden firma listesinde görünmüyor?</summary><p>Firma onayının yanında üyeliğinizin aktif olması ve Profil sayfasındaki rehber görünürlüğünün açık olması gerekir. Katalog ürünlerinin görünmesi için ürünleri ayrıca yayınlamalısınız; gizli ürünler ziyaretçilere gösterilmez.</p></details>
    <details><summary>Firma logosu ve ürün kataloğunu nasıl eklerim?</summary><p>Firma hesabınızla Profil sayfasından logonuzu yükleyebilir, katalog alanında ürün bilgileri ve fotoğraflarını ekleyebilirsiniz. Ürününüze uygun PDF katalog veya video ekleyerek teknik ayrıntıları paylaşabilir, yayın durumunu buradan yönetebilirsiniz.</p></details>
    <details><summary>Onay e-postası gelmezse veya şifremi unutursam ne yapmalıyım?</summary><p>Önce spam ve gereksiz klasörlerini kontrol edin. Giriş ekranından onay e-postasını yeniden gönderebilir veya “Şifremi unuttum” bağlantısıyla sıfırlama bağlantısı isteyebilirsiniz. Sorun sürerse <a href="mailto:info@marbleborsa.com">info@marbleborsa.com</a> adresine yazın; şifrenizi paylaşmayın.</p></details>
    </section>`) : withEditorial;
  let directoryEnhanced = enhanced;
  if (directory && category && ["dogal-tas","makine-sarf","hizmetler"].includes(category)) {
    const section = category === "dogal-tas" ? "companies" : category === "makine-sarf" ? "machines" : "services";
    const matches = directory.companies.filter(company => company.section === section);
    directoryEnhanced = enhanced
      .replace('id="categoryCompanies" aria-labelledby="categoryCompaniesTitle" hidden', 'id="categoryCompanies" aria-labelledby="categoryCompaniesTitle"')
      .replace('<h4 id="categoryCompaniesTitle"></h4>', `<h4 id="categoryCompaniesTitle">${category === "dogal-tas" ? "Doğal taş üreticileri ve tedarikçileri" : category === "makine-sarf" ? "Makine ve sarf firmaları" : "Hizmet firmaları"}</h4>`)
      .replace('<div class="category-companies-list" id="categoryCompaniesList"></div>', `<div class="category-companies-list" id="categoryCompaniesList">${matches.map(company => `<article class="category-company">${logo(company)}<div><strong>${escape(company.name)}</strong><span>${escape(company.city)}</span><a href="/tr/firmalar/${escape(company.id)}">Firma profili ve katalog →</a></div></article>`).join("")}</div>`)
      .replace('<p class="category-companies-empty" id="categoryCompaniesEmpty" role="status"></p>', `<p class="category-companies-empty" id="categoryCompaniesEmpty" role="status"${matches.length ? " hidden" : ""}>${matches.length ? "" : directory.status === "error" ? "Firma bilgisi alınamadı. Sayfayı tekrar deneyin." : "Bu kategoride henüz yayınlanmış firma bulunmuyor."}</p>`);
  }
  if (category && ["dogal-tas","makine-sarf","hizmetler"].includes(category)) {
    const block = directoryEnhanced.match(/<section class="category-companies"[\s\S]*?<\/section>/)?.[0];
    if (block) directoryEnhanced = directoryEnhanced.replace(block, "").replace('<div id="cards"', block + '<div id="cards"');
  }
  const result = profile ? directoryEnhanced
    .replace('<main>', '<main class="profile-page">')
    .replace('id="workspace" aria-labelledby="workspaceTitle" hidden', 'id="workspace" aria-labelledby="workspaceTitle"')
    .replace('<h2 id="workspaceTitle"></h2>', '<h1 id="workspaceTitle">Profil</h1>')
    .replace('<div id="workspaceContent"></div>', '<div id="workspaceContent"><div class="profile-welcome"><strong>Profilinize giriş yapın</strong><p>Taleplerinizi, tekliflerinizi ve firma bilgilerinizi hesabınızdan yönetin.</p><button type="button" class="button dark" data-profile-login>Giriş Yap</button><button type="button" class="button outline" data-signup-open>Hesap Oluştur</button></div></div>') : directoryEnhanced;
  const faqPattern = /<section class="seo-help" aria-labelledby="market-faq">[\s\S]*?<\/section>/;
  const faq = result.match(faqPattern)?.[0];
  const arranged = faq ? result.replace(faqPattern, "").replace('<section class="market-guide-preview"', faq + '\n<section class="market-guide-preview"') : result;
  const prepared = !category || category === "alim-talepleri" ? arranged.replace('class="toolbar"','class="toolbar" hidden') : arranged;
  const shaped=category && category!=="dogal-tas" ? prepared.replace('id="stoneGallery"','hidden id="stoneGallery"').replace('id="browseButton">Taşları keşfet','id="browseButton">Listeyi incele') : prepared;
  return shaped.replace('id="categoryCompaniesAction" data-signup-open>','id="categoryCompaniesAction" data-signup-open hidden>').replace(/<div class="info-strip">[\s\S]*?<\/header>/, "").replace(/<footer>[\s\S]*?<\/footer>/, "").replace(/<main(?=[ >])/, '<main id="main-content" tabindex="-1"');
}

