export function localizedMarkup(category: MarketplaceCategory | undefined, profile: boolean, directory: DirectorySeed, locale: 'tr'|'en'|'zh'|'ar') {
 let html=marketMarkup(category,profile,directory);
 if(locale==='tr')return html;
 const langIndex=locale==='en'?1:locale==='zh'?2:3;
 const homeCopy=localizedUi.home[locale];
 if(!category){
  const tabs=['stones','companies','machines','services'] as const;
  const segments=['natural-stone','companies','machinery-supplies','services'];
  const images=['/market/images/marble/white.webp','/market/images/marble/beige.webp','/market/images/machines/elmas-tel.webp','/market/images/services/lojistik.webp'];
  let i=0;
  html=html.replace(/<article class="discovery-card">[\s\S]*?<\/article>/g,()=>{const index=i++; const [title,description]=homeCopy.cards[index];return `<article class="discovery-card"><a class="discovery-link" data-tab="${tabs[index]}" href="/${locale}/${segments[index]}"><span class="discovery-media"><img src="${images[index]}" width="560" height="360" loading="lazy" alt="${escape(title)}"/></span><span class="discovery-copy"><small>0${index+1} / MARBLE BORSA</small><strong>${escape(title)}</strong><span>${escape(description)}</span><b>${escape(homeCopy.action)} ↗</b></span></a></article>`;});
 }
 const protectedBlocks:string[]=[];
 html=html.replace(/<script[\s\S]*?<\/script>|<article class="(?:card card-real|category-company)"[\s\S]*?<\/article>|<a class="company-row"[\s\S]*?<\/a>/g,block=>{protectedBlocks.push(block);return `MBPROTECTED${protectedBlocks.length-1}END`;});
 const t=localizedUi.copy[locale],home=localizedUi.home[locale];
 const tab=category==='dogal-tas'?0:category==='firmalar'?1:category==='makine-sarf'?2:3;
 const fields:Record<string,string>={heroTitle:category==='alim-talepleri'?({en:"Buying Requests",zh:"采购需求",ar:"طلبات الشراء"})[locale]:category?t.panelTitles[tab]:t.heroTitle,heroLead:t.heroLead,heroEyebrow:t.heroEyebrow,heroFoot:t.heroFoot,marketHeading:home.heading,marketIntro:home.intro,panelTitle:category==='alim-talepleri'?({en:"Buying Requests",zh:"采购需求",ar:"طلبات الشراء"})[locale]:category?t.panelTitles[tab]:home.section,panelSubtitle:category?t.panelSubs[tab]:home.subtitle,browseButton:t.browse,newRequestButton:t.newRequest,asideTitle:t.asideTitle,asideBody:t.asideBody,categoriesLabel:t.categories,resetSearch:t.reset,flowLabel:t.flow,flow1:t.flowSteps[0],flow2:t.flowSteps[1],flow3:t.flowSteps[2]};
 for(const [id,text] of Object.entries(fields))html=html.replace(new RegExp(`(<(?:h[1-6]|p|span|button|small|strong)[^>]*id="${id}"[^>]*>)[\\s\\S]*?(</(?:h[1-6]|p|span|button|small|strong)>)`),`$1${escape(text)}$2`);
 const dictionary:Record<string,string>={"Alım taleplerini görüntülemek için firma hesabınızla giriş yapın.":locale==='en'?'Sign in with a company account to view buying requests.':locale==='zh'?'请使用企业账户登录以查看采购需求。':'سجل الدخول بحساب شركة لعرض طلبات الشراء.',"Giriş Yap":t.signIn,"Firma Hesabı Oluştur":locale==='en'?'Create Company Account':locale==='zh'?'创建企业账户':'إنشاء حساب شركة',"Firma katalogları":locale==='en'?'Company catalogues':locale==='zh'?'企业目录':'كتالوج الشركات',"Tür rehberi":locale==='en'?'Category guide':locale==='zh'?'类别指南':'دليل الفئات',"Bu kategoride henüz yayınlanmış firma kataloğu bulunmuyor.":locale==='en'?'No published company catalogue in this category yet.':locale==='zh'?'此类别尚无已发布的企业目录。':'لا توجد كتالوجات منشورة في هذه الفئة بعد.',"Doğal taş üreticileri ve tedarikçileri":locale==='en'?'Natural stone producers and suppliers':locale==='zh'?'天然石材生产商与供应商':'منتجو وموردو الحجر الطبيعي',"Makine ve sarf firmaları":t.panelTitles[2],"Hizmet firmaları":t.panelTitles[3],"Firma profili ve katalog":t.firmDetail,"Firma profili":t.firmDetail,"Detayları gör":t.details,"Keşfet":home.action,"Taş, makine ve hizmet türlerini inceleyin.":home.intro,"Bu kategoride henüz yayınlanmış firma bulunmuyor.":locale==='en'?'No listed company in this category yet.':locale==='zh'?'此类别尚无企业。':'لا توجد شركة مدرجة في هذه الفئة بعد.',"Taşları keşfet":t.browse,"TÜR REHBERİ":locale==='en'?'CATEGORY GUIDE':locale==='zh'?'类别指南':'دليل الفئات',"FİRMA KATALOĞU":locale==='en'?'COMPANY CATALOGUE':locale==='zh'?'企业目录':'كتالوج الشركة',"Kataloğu incele":locale==='en'?'View catalogue':locale==='zh'?'查看目录':'عرض الكتالوج'};
 for(const [tr,text] of Object.entries(dictionary).sort((a,b)=>b[0].length-a[0].length))html=html.split(tr).join(escape(text));
 if(category==='hizmetler'||category==='makine-sarf'){
  const rows=category==='hizmetler'?localizedUi.services:localizedUi.machines;const index=locale==='en'?1:locale==='zh'?2:3;
  for(const row of rows){html=html.split(row.name[0]).join(row.name[index]);html=html.split(row.field[0]).join(row.field[index]);}
 }
 if(!category)for(let i=0;i<home.cards.length;i++){const tr=localizedUi.home.tr.cards[i];html=html.split(tr[0]).join(home.cards[i][0]).split(tr[1]).join(home.cards[i][1]);}
 // Turkish long-form buying and legal guides have their own explicit locale routes.
 html=html.replace(/<section class="(?:seo-help[^"\n]*|market-guide-preview|market-sourcing-preview|market-editorial)"[\s\S]*?<\/section>/g,'');
 const requests=({en:'Buying Requests',zh:'采购需求',ar:'طلبات الشراء'})[locale];
 const sideTitles=[homeCopy.home,...localizedUi.copy[locale].nav.slice(0,2),localizedUi.copy[locale].nav[2],localizedUi.copy[locale].nav[3],requests];
 const sidePaths=[`/${locale}`,`/${locale}/natural-stone`,`/${locale}/companies`,`/${locale}/machinery-supplies`,`/${locale}/services`,`/${locale}/buying-requests`];
 html=html.replace(/<div id="sideNav">[\s\S]*?<\/div>/,`<div id="sideNav">${sideTitles.map((title,index)=>`<a href="${sidePaths[index]}" data-tab="${['home','stones','companies','machines','services','requests'][index]}">${escape(title)}<b>›</b></a>`).join('')}</div>`);
 html=html.replace('DOĞAL TAŞ KOLEKSİYONU',({en:'NATURAL STONE COLLECTION',zh:'天然石材系列',ar:'مجموعة الحجر الطبيعي'})[locale]);
 return html.replace(/MBPROTECTED(\d+)END/g,(_,index)=>protectedBlocks[Number(index)]);
}
